import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        address ownerBefore = c.owner();
        try c.setOwner(_newOwner) {
            // call succeeded
        } catch {
            // call reverted
        }
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore, "Owner should not change after setOwner call");
    }
